import sys

def main():
    s = sys.stdin.read().split()[0]
    n = len(s)
    if n < 3:
        print('false')
        return
    pal = [None] * (n + 1)
    pal[n] = bytearray(n)
    for i in range(n - 1, -1, -1):
        row = bytearray(n)
        nxt = pal[i + 1]
        ci = s[i]
        row[i] = 1
        for j in range(i + 1, n):
            if s[j] == ci and (j - i < 2 or nxt[j - 1]):
                row[j] = 1
        pal[i] = row
    first = pal[0]
    for i in range(n - 2):
        if not first[i]:
            continue
        mid = pal[i + 1]
        for j in range(i + 1, n - 1):
            if mid[j] and pal[j + 1][n - 1]:
                print('true')
                return
    print('false')

